public abstract class Customer {                       // shared ops + role protocol
  public abstract <T extends CustomerRole> T addRole(Class<T> spec);
  public abstract <T extends CustomerRole> T getRole(Class<T> spec);
}
public final class CustomerCore extends Customer {
  private final Map<Class<?>, CustomerRole> roles = new HashMap<>();
  public <T extends CustomerRole> T getRole(Class<T> spec) { return spec.cast(roles.get(spec)); }
  public <T extends CustomerRole> T addRole(Class<T> spec) {               // core owns its roles
    return roles.computeIfAbsent(spec, s -> CustomerRole.createFor(s, this));
  }
}
